import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from modules.testing import TUITestFramework, TestStep

# Create framework with custom SDK init wait time
# Default is 11 seconds - time to wait for opencli SDK to initialize
framework = TUITestFramework(sdk_init_wait=11)

# Build custom test sequence
print("Building test sequence...")
print("")

# Step 1: Type the command
framework.add_step(
    TestStep.TYPE,
    "/help",
    "Type /help command",
    wait_after=1
)

# Step 2: Autocomplete (first ENTER)
framework.add_step(
    TestStep.ENTER,
    description="Autocomplete command",
    wait_after=1
)

# Step 3: Submit command (second ENTER)
framework.add_step(
    TestStep.ENTER,
    description="Submit command to show permission buffer",
    wait_after=4
)

# Step 4: Collect initial state
framework.add_step(
    TestStep.COLLECT_STATE,
    description="Collect permission buffer state",
    wait_after=2
)

# Step 5: Test DOWN arrow navigation
# AUTO-DETECTION: Framework automatically captures BEFORE and AFTER states
framework.add_step(
    TestStep.DOWN,
    description="Press DOWN arrow to select 'No'",
    wait_after=2
)

# Step 6: Verify selection changed
framework.add_step(
    TestStep.VERIFY_SELECTION,
    description="Verify 'No' is now selected",
    expected_state={"selected": "No"},
    wait_after=1
)

# Step 7: Test UP arrow navigation
framework.add_step(
    TestStep.UP,
    description="Press UP arrow to select 'Yes'",
    wait_after=2
)

# Step 8: Verify selection changed back
framework.add_step(
    TestStep.VERIFY_SELECTION,
    description="Verify 'Yes' is now selected",
    expected_state={"selected": "Yes"},
    wait_after=1
)

# Step 9: Confirm selection
framework.add_step(
    TestStep.ENTER,
    description="Confirm selection",
    wait_after=2
)

print("Running custom test sequence...")
print("Visual mode: Two Terminal windows will open")
print("")

# Run test with visual mode
result = framework.run_test(visual=True)

# Show results
print("")
print("=" * 60)
print("NAVIGATION TEST RESULTS")
print("=" * 60)

if result.passed:
    print("✅ Navigation test PASSED")
    print("   Arrow keys working correctly")
    print("   Selection changes detected")
else:
    print("❌ Navigation test FAILED")
    print(f"   {result.message}")

# Cleanup
framework.cleanup()
