import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from modules.testing import create_permission_buffer_test

# List of commands to test
commands = ["/help", "/agent", "/model"]

print("Testing multiple commands...")
print(f"Commands to test: {', '.join(commands)}")
print("")

results = {}

for cmd in commands:
    print(f"Testing {cmd}...")
    test = create_permission_buffer_test(command=cmd)
    result = test.run_test(visual=False)
    results[cmd] = result

    status = "✅ PASSED" if result.passed else "❌ FAILED"
    print(f"  {status}")

    test.cleanup()

# Summary report
print("")
print("=" * 60)
print("SUMMARY REPORT")
print("=" * 60)

passed = sum(1 for r in results.values() if r.passed)
total = len(results)

print(f"Total commands tested: {total}")
print(f"Passed: {passed}")
print(f"Failed: {total - passed}")
print("")

for cmd, result in results.items():
    status = "✅" if result.passed else "❌"
    print(f"{status} {cmd}")
    if not result.passed:
        print(f"   → {result.message}")

# Exit with failure if any test failed
exit_code = 0 if all(r.passed for r in results.values()) else 1
sys.exit(exit_code)
