import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from modules.testing import TUITestFramework, TestStep

# Define custom validation function
def verify_permission_buffer_displayed(state):
    """
    Custom verify function that checks if permission buffer is displayed.

    Args:
        state (dict): Current TUI state from COLLECT_STATE

    Returns:
        bool: True if validation passes, False otherwise
    """
    output = state.get('output', '')

    # Check for expected elements
    has_yes_option = 'Yes' in output
    has_no_option = 'No' in output
    has_system_prefix = 'System:' in output

    print(f"  Checking permission buffer elements:")
    print(f"    Has 'Yes' option: {has_yes_option}")
    print(f"    Has 'No' option: {has_no_option}")
    print(f"    Has 'System:' prefix: {has_system_prefix}")

    return has_yes_option and has_no_option and has_system_prefix

# Create framework
framework = TUITestFramework(sdk_init_wait=11)

# Build test with custom validation
framework.add_step(TestStep.TYPE, "/help", "Type command")
framework.add_step(TestStep.ENTER, description="Autocomplete")
framework.add_step(TestStep.ENTER, description="Submit", wait_after=4)

# Use custom verify function
framework.add_step(
    TestStep.COLLECT_STATE,
    description="Verify permission buffer with custom logic",
    verify_fn=verify_permission_buffer_displayed,
    wait_after=2
)

print("Running test with custom validation...")
print("")

result = framework.run_test(visual=True)

print("")
print("=" * 60)
print("CUSTOM VALIDATION RESULTS")
print("=" * 60)

if result.passed:
    print("✅ Custom validation PASSED")
else:
    print("❌ Custom validation FAILED")
    print(f"   {result.message}")

framework.cleanup()
