import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from modules.testing import TUITestFramework, TestStep

framework = TUITestFramework(sdk_init_wait=11)

# Collect state at multiple checkpoints
print("Building test with state collection checkpoints...")
print("")

# Checkpoint 1: Initial state
framework.add_step(
    TestStep.COLLECT_STATE,
    description="CHECKPOINT 1: Initial TUI state",
    wait_after=1
)

# Submit command
framework.add_step(TestStep.TYPE, "/help")
framework.add_step(TestStep.ENTER)
framework.add_step(TestStep.ENTER, wait_after=4)

# Checkpoint 2: Permission buffer displayed
framework.add_step(
    TestStep.COLLECT_STATE,
    description="CHECKPOINT 2: Permission buffer displayed",
    wait_after=2
)

# Navigate down
framework.add_step(TestStep.DOWN, description="Navigate to 'No'", wait_after=2)

# Checkpoint 3: After navigation
framework.add_step(
    TestStep.COLLECT_STATE,
    description="CHECKPOINT 3: After DOWN navigation",
    wait_after=1
)

# Navigate up
framework.add_step(TestStep.UP, description="Navigate to 'Yes'", wait_after=2)

# Checkpoint 4: After second navigation
framework.add_step(
    TestStep.COLLECT_STATE,
    description="CHECKPOINT 4: After UP navigation",
    wait_after=1
)

print("Running test with state collection...")
print("")

result = framework.run_test(visual=True)

print("")
print("=" * 60)
print("STATE COLLECTION ANALYSIS")
print("=" * 60)

if result.passed:
    print("✅ Test PASSED")
    print("")
    print("State was collected at 4 checkpoints:")
    print("  1. Initial TUI state")
    print("  2. Permission buffer displayed")
    print("  3. After DOWN navigation")
    print("  4. After UP navigation")
    print("")
    print("Review log file for detailed state data:")
    print(f"  {result.log_file}")
else:
    print("❌ Test FAILED")
    print(f"   {result.message}")

framework.cleanup()
